"""Underline all headline paragraphs in the unpacked quarterly report."""
import os
import sys

sys.path.insert(0, os.path.join(os.getcwd(), ".codex", "skills", "docx"))

from scripts.document import Document


def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        for child in t.childNodes:
            if child.nodeType == child.TEXT_NODE:
                parts.append(child.data)
    return "".join(parts)


def is_headline(text):
    letters = [c for c in text if c.isalpha()]
    return bool(letters) and all(c.isupper() for c in letters)


doc = Document("unpacked", rsid="0D028BD4")
editor = doc["word/document.xml"]
dom = editor.dom

headlines = []
for p in dom.getElementsByTagName("w:p"):
    text = para_text(p)
    if not is_headline(text):
        continue
    headlines.append(text)
    for r in p.getElementsByTagName("w:r"):
        rpr_list = r.getElementsByTagName("w:rPr")
        if not rpr_list:
            continue
        rpr = rpr_list[0]
        if rpr.getElementsByTagName("w:u"):
            continue
        u = dom.createElement("w:u")
        u.setAttribute("w:val", "single")
        rpr.appendChild(u)

print("Headlines underlined (%d):" % len(headlines))
for h in headlines:
    print("  - " + h)

doc.save()
print("Saved.")

